def transform(grid):
    import collections
    H,W=len(grid),len(grid[0])
    seeds=[(r,c,grid[r][c]) for r in range(H) for c in range(W) if grid[r][c] not in (0,1)]
    # flood components of 1s
    seen=set(); comp={}
    cid={}
    for r in range(H):
        for c in range(W):
            if grid[r][c]==1 and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    rr,cc=q.popleft(); cells.append((rr,cc))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and grid[nr][nc]==1 and (nr,nc) not in seen:
                            seen.add((nr,nc)); q.append((nr,nc))
                for x in cells: cid[x]=len(comp)
                comp[len(comp)]=cells
    # map each seed to adjacent component
    seedcolor={}
    for r,c,v in seeds:
        adj=set()
        for dr in(-1,0,1)for dc in(-1,0,1):
            if (dr,dc)!=(0,0):
                x=(r+dr,c+dc)
                if x in cid: adj.add(cid[x])
        for a in adj: seedcolor[a]=v
    out=[row[:] for row in grid]
    for r in range(1,H-1):
        for c in range(1,W-1):
            if all(grid[r+dr][c+dc]!=0 for dr in(-1,0,1) for dc in(-1,0,1)):
                col=seedcolor.get(cid.get((r,c)))
                if col is None:
                    # nearest seed
                    col=min(seeds,key=lambda s:(abs(s[0]-r)+abs(s[1]-c)))[2]
                out[r][c]=col
    return out
